function loadChapterHeader(){const n=document.querySelector("header");if(!n)return;const e=window.location.pathname;let s="Class 9";e.includes("class-10")?s="Class 10":e.includes("class-11")?s="Class 11":e.includes("class-12")&&(s="Class 12");const t=e.includes("/sample-papers/"),l=t?"../../../":"../../../../",i=t?"../":"../../";n.innerHTML=`
        <a href="${l}" class="logo">
            <span style="font-size: 1.5em;">&int;</span> SJMaths
        </a>
        <div style="display: flex; align-items: center; gap: 10px;">
            <a href="${i}" class="nav-btn" style="font-size: 0.9rem; padding: 5px 15px;">
                <i class="fas fa-graduation-cap"></i> ${s}
            </a>
        </div>
    `;const a=document.querySelector("#darkToggle i");document.body.classList.contains("dark-mode")&&a&&(a.classList.remove("fa-moon"),a.classList.add("fa-sun"))}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",loadChapterHeader):loadChapterHeader();
